import React, { useEffect, useMemo, useState, useCallback } from 'react';
import type { TabKey } from '../components/TabNav';
import './Accueil.css';

const slides = [
  { src: '/assets/hero-clean.jpg',   alt: "Vitres impeccables après intervention" },
  { src: '/assets/hero-clean-2.jpg', alt: "Postes de travail alignés et propres" },
  { src: '/assets/hero-clean-3.jpg', alt: "Hall d’immeuble brillant après entretien" },
];

export default function Accueil({ goTo }: { goTo: (k: TabKey) => void }) {
  const [i, setI] = useState(0);
  const reduceMotion = useMemo(
    () => typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,
    []
  );

  useEffect(() => {
    if (reduceMotion || slides.length < 2) return;
    const t = setInterval(() => setI(v => (v + 1) % slides.length), 5000);
    return () => clearInterval(t);
  }, [reduceMotion]);

  const go = useCallback((dir: 1 | -1) => {
    setI(v => (v + dir + slides.length) % slides.length);
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight') go(1);
      if (e.key === 'ArrowLeft') go(-1);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [go]);

  return (
    <section className="accueil-hero" aria-label="Bienvenue chez +Propre">
      {/* Фон-слайдшоу */}
      <div className="accueil-hero__bg" aria-hidden="true">
        {slides.map((s, idx) => (
          <img
            key={s.src}
            src={s.src}
            alt=""
            className={`accueil-hero__bg-img ${idx === i ? 'is-active' : ''}`}
            loading={idx === 0 ? 'eager' : 'lazy'}
          />
        ))}
        <div className="accueil-hero__vignette" />
        <div className="accueil-hero__glow" />
      </div>

      {/* Стеклянная панель с контентом */}
      <div className="accueil-hero__panel">
        <div className="accueil-hero__brand">
          <div className="accueil-hero__logo" aria-hidden>+</div>
          <div>
            <div className="accueil-hero__title">+Propre</div>
            <div className="accueil-hero__tag">Nettoyage & entretien professionnels</div>
          </div>
        </div>

        <h1 className="accueil-hero__h1">
          Le nettoyage pro qui fait <span className="accent">briller</span> vos espaces.
        </h1>

        <p className="accueil-hero__lede">
          Bureaux, cabinets médicaux, commerces, copropriétés, locations courte durée, fins de bail & de chantier.
          Des protocoles d’hygiène exigeants, une traçabilité claire, des délais tenus.
        </p>

        <div className="accueil-hero__cta">
          <button className="btn btn-primary btn-xl" onClick={() => goTo('contact')}>
            Demander un devis
          </button>
          <button className="btn btn-ghost btn-xl" onClick={() => goTo('realisations')}>
            Voir nos réalisations
          </button>
        </div>

        <div className="accueil-hero__chips" role="list" aria-label="Indicateurs de confiance">
          <div className="chip"><strong>24h</strong><span>Devis</span></div>
          <div className="chip"><strong>7j/7</strong><span>Flexibilité</span></div>
          <div className="chip"><strong>100%</strong><span>Équipe assurée</span></div>
          <div className="chip"><strong>Éco</strong><span>Produits</span></div>
        </div>

        {/* Навигация слайдера */}
        <div className="accueil-hero__nav">
          <button className="nav-btn" onClick={() => go(-1)} aria-label="Image précédente">‹</button>
          <div className="dots" role="tablist" aria-label="Sélecteur d'image">
            {slides.map((_, idx) => (
              <button
                key={idx}
                role="tab"
                aria-selected={idx === i}
                className={`dot ${idx === i ? 'is-active' : ''}`}
                onClick={() => setI(idx)}
              />
            ))}
          </div>
          <button className="nav-btn" onClick={() => go(1)} aria-label="Image suivante">›</button>
        </div>

        {/* Статусная полоска */}
        <div className="accueil-hero__status" aria-hidden="true">
          Couverture Île-de-France • Protocoles sectoriels • Contrôle qualité
        </div>
      </div>
    </section>
  );
}
